#!/usr/bin/env python3
"""Build the standalone ChipVerify memory-engine bundle."""
import argparse
import hashlib
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check',action='store_true')
args=parser.parse_args()
sources=['rtl/p04_dot4.sv','rtl/p04_scratchpad.sv','rtl/p04_dot4_engine.sv']
outputs={
    'design.sv':'// Generated by scripts/bundle_memory_engine.py\n'+'\n'.join((ROOT/p).read_text() for p in sources),
    'testbench.sv':(ROOT/'tb/tb_p04_dot4_engine.sv').read_text()
}
target=ROOT/'sim/chipverify_memory'
target.mkdir(parents=True,exist_ok=True)
for name,content in outputs.items():
    path=target/name
    if args.check:
        if not path.exists() or path.read_text()!=content:
            raise SystemExit(f'Stale bundle: {path}')
    else:path.write_text(content)
    print(f'{path.relative_to(ROOT)} sha256={hashlib.sha256(content.encode()).hexdigest()}')
